8	6	WITH ProductAvgRatings AS (\r\n    SELECT\r\n        r.product_id,\r\n        AVG(r.rating) AS avg_product_rating\r\n    FROM Reviews r\r\n    GROUP BY r.product_id\r\n),\r\nCustomerGenerosity AS (\r\n    SELECT\r\n        r.customer_id,\r\n        AVG(r.rating / pa.avg_product_rating) AS avg_generosity\r\n    FROM Reviews r\r\n    JOIN ProductAvgRatings pa ON r.product_id = pa.product_id\r\n    GROUP BY r.customer_id\r\n),\r\nScaledRatings AS (\r\n    SELECT\r\n        r.product_id,\r\n        r.rating / cg.avg_generosity AS scaled_rating\r\n    FROM Reviews r\r\n    JOIN CustomerGenerosity cg ON r.customer_id = cg.customer_id\r\n),\r\nProductScaledAvgRatings AS (\r\n    SELECT\r\n        sr.product_id,\r\n        AVG(sr.scaled_rating) AS scaled_avg_rating\r\n    FROM ScaledRatings sr\r\n    GROUP BY sr.product_id\r\n),\r\nMaxScaledAvgRating AS (\r\n    SELECT MAX(scaled_avg_rating) AS max_scaled_rating\r\n    FROM ProductScaledAvgRatings\r\n)\r\nSELECT\r\n    psar.product_id,\r\n    psar.scaled_avg_rating\r\nFROM ProductScaledAvgRatings psar\r\nJOIN MaxScaledAvgRating msar ON psar.scaled_avg_rating = msar.max_scaled_rating;\r\n\r\n\t\t\t\t\t\t\t	cs387iitb_5705	1	100	{"AssignmentId":0,"QuestionId":0,"QueryId":0,"Relation":0,"Predicate":1,"Projection":1,"Joins":1,"WhereSubQueries":1,"FromSubQueries":1,"OuterQuery":1,"GroupBy":1,"HavingClause":1,"SubQConnective":1,"Aggregates":1,"SetOperators":1,"Distinct":1,"maxPartialMarks":90}	{"AssignmentId":0,"QuestionId":0,"QueryId":0,"Relation":0,"Predicate":1,"Projection":1,"Joins":1,"WhereSubQueries":1,"FromSubQueries":1,"OuterQuery":1,"GroupBy":1,"HavingClause":1,"SubQConnective":1,"Aggregates":1,"SetOperators":1,"Distinct":1,"maxPartialMarks":90}	{"status":"passed","Marks":0.0,"maxMarks":0.0,"ErrorMessage":"","queryId":0,"dataSetIdList":[],"dsValueMap":{},"studentQueryOutput":{},"instrQueryOutput":{},"failedDefaultDataSets":[null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,