cs387iitb_5705	4	ecommercedb	DROP TABLE IF EXISTS Customers CASCADE;\nDROP TABLE IF EXISTS Categories CASCADE;\nDROP TABLE IF EXISTS Suppliers CASCADE;\nDROP TABLE IF EXISTS Products CASCADE;\nDROP TABLE IF EXISTS Orders CASCADE;\nDROP TABLE IF EXISTS OrderItems CASCADE;\nDROP TABLE IF EXISTS Shipping CASCADE;\nDROP TABLE IF EXISTS Payments CASCADE;\nDROP TABLE IF EXISTS Reviews CASCADE;\n\nCREATE TABLE Customers (\n    customer_id INT PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    email VARCHAR(100) UNIQUE NOT NULL,\n    phone_number VARCHAR(10)\n);\n\nCREATE TABLE Categories (\n    category_id INT PRIMARY KEY,\n    name VARCHAR(50) NOT NULL,\n    description TEXT\n);\n\nCREATE TABLE Suppliers (\n    supplier_id INT PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    email VARCHAR(100),\n    phone_number VARCHAR(15),\n    address TEXT\n);\n\nCREATE TABLE Products (\n    product_id INT PRIMARY KEY,\n    supplier_id INT REFERENCES Suppliers(supplier_id),\n    category_id INT REFERENCES Categories(category_id),\n    name VARCHAR(100) NOT NULL,\n    price DECIMAL(10, 2) NOT NULL,\n    quantity INT NOT NULL\n);\n\nCREATE TABLE Orders (\n    order_id INT PRIMARY KEY,\n    customer_id INT REFERENCES Customers(customer_id),\n    order_date DATE NOT NULL,\n    total_amount DECIMAL(10,2) NOT NULL\n);\n\nCREATE TABLE OrderItems(\n    order_id INT REFERENCES Orders(order_id),\n    product_id INT REFERENCES Products(product_id),\n    quantity INT NOT NULL,\n    price DECIMAL(10, 2) NOT NULL, -- Unit price per item\n    PRIMARY KEY (order_id, product_id)\n);\n\nCREATE TABLE Payments (\n    payment_id INT PRIMARY KEY,\n    order_id INT REFERENCES Orders(order_id),\n    payment_date DATE,\n    payment_method VARCHAR(20) CHECK (payment_method IN ('UPI', 'Net Banking', 'Debit Card', 'Credit Card', 'Cash on Delivery'))\n);\n\n\nCREATE TABLE Shipping (\n    shipping_id INT PRIMARY KEY,\n    order_id INT REFERENCES Orders(order_id),\n    shipping_method VARCHAR(20) CHECK (shipping_m